import { irr, npv } from './finance'
import { lineTotal } from './lines'
import { paymentRows } from './payments'
import { round2 } from './format'
import type { Project } from './types'

export interface MonthRow {
  readonly month: string
  readonly capex: number
  readonly exportedMw: number
  readonly revenue: number
  readonly power: number
  readonly staff: number
  readonly maintenance: number
  readonly insurance: number
  readonly opex: number
  readonly ebitda: number
  readonly depreciation: number
  readonly ebit: number
  readonly tax: number
  readonly netIncome: number
  readonly freeCash: number
  readonly cumulativeCash: number
}

export interface ProjectionSummary {
  readonly totalCapex: number
  readonly peakFunding: number
  readonly paybackMonth: string | null
  readonly breakEvenMonth: string | null
  readonly npv: number
  readonly irr: number | null
  readonly stabilisedEbitda: number
  readonly stabilisedRevenue: number
}

export interface Projection {
  readonly months: readonly MonthRow[]
  readonly summary: ProjectionSummary
}

export interface YearRow {
  readonly year: number
  readonly capex: number
  readonly revenue: number
  readonly opex: number
  readonly ebitda: number
  readonly depreciation: number
  readonly tax: number
  readonly netIncome: number
  readonly freeCash: number
}

const HOURS_PER_MONTH = 730
const DEFAULT_BUILDING_LIFE_YEARS = 25

/** Compounding factor for year-on-year indexation, stepping once per operating year. */
const indexation = (annualRate: number, opMonth: number): number => (1 + annualRate) ** Math.floor(opMonth / 12)

export function projectionFlows(rows: readonly MonthRow[]): number[] {
  return rows.map((r) => r.freeCash)
}

/** Builds the monthly model from a resolved project. Pure and deterministic. */
export function runProjection(resolved: Project): Projection {
  const d = resolved.drivers
  const startKey = monthKey(resolved.startDate)

  const capexByMonth = new Map<string, number>()
  for (const row of paymentRows(resolved)) {
    const key = monthKey(row.paidDate ?? row.dueDate)
    capexByMonth.set(key, (capexByMonth.get(key) ?? 0) + row.amount)
  }

  const totalCapex = resolved.lines.reduce((sum, l) => sum + lineTotal(l), 0)
  const assetCapex = resolved.lines.filter((l) => l.kind === 'asset').reduce((sum, l) => sum + lineTotal(l), 0)

  let cumulative = 0
  const months: MonthRow[] = Array.from({ length: d.horizonMonths }, (_, i) => {
    const month = shiftMonth(startKey, i)
    const opMonth = diffMonths(d.goLive, month)
    const operating = opMonth >= 0

    const exportedMw = operating ? d.capacityMwac * d.capacityFactor * Math.min(1, (opMonth + 1) / d.rampMonths) : 0
    const index = operating ? indexation(d.inflationPct, opMonth) : 1
    const revenue = exportedMw * 1000 * d.revenuePerKwMonth * index
    const power = exportedMw * 1000 * HOURS_PER_MONTH * d.variableOmPerKwh * index
    const staff = operating ? d.staffCostMonthly * index : 0
    const maintenance = operating ? (assetCapex * d.maintenancePct) / 12 : 0
    const insurance = operating ? (totalCapex * d.insurancePct) / 12 : 0
    const opex = power + staff + maintenance + insurance
    const ebitda = revenue - opex

    const depreciation = operating
      ? resolved.lines.reduce((sum, l) => {
          const years = l.asset?.depreciationYears ?? DEFAULT_BUILDING_LIFE_YEARS
          return opMonth < years * 12 ? sum + lineTotal(l) / (years * 12) : sum
        }, 0)
      : 0
    const ebit = ebitda - depreciation
    const tax = Math.max(0, ebit) * d.taxRate
    const capex = capexByMonth.get(month) ?? 0
    const freeCash = ebitda - tax - capex
    cumulative += freeCash

    return {
      month,
      capex: round2(capex),
      exportedMw,
      revenue: round2(revenue),
      power: round2(power),
      staff: round2(staff),
      maintenance: round2(maintenance),
      insurance: round2(insurance),
      opex: round2(opex),
      ebitda: round2(ebitda),
      depreciation: round2(depreciation),
      ebit: round2(ebit),
      tax: round2(tax),
      netIncome: round2(ebit - tax),
      freeCash: round2(freeCash),
      cumulativeCash: round2(cumulative),
    }
  })

  return { months, summary: summarise(months, resolved) }
}

function summarise(months: readonly MonthRow[], resolved: Project): ProjectionSummary {
  const goLive = resolved.drivers.goLive
  const flows = projectionFlows(months)
  const firstOperating = months.findIndex((m) => m.month >= goLive)
  const stabilisedIndex = Math.min(months.length - 1, Math.max(0, firstOperating) + resolved.drivers.rampMonths + 11)
  const stabilisedYear = months.slice(stabilisedIndex - 11, stabilisedIndex + 1)

  const paybackIndex = months.findIndex((m, i) => i > firstOperating && m.cumulativeCash >= 0)
  const breakEven = months.find((m) => m.month >= goLive && m.ebitda > 0)

  return {
    totalCapex: round2(months.reduce((sum, m) => sum + m.capex, 0)),
    peakFunding: round2(-Math.min(0, ...months.map((m) => m.cumulativeCash))),
    paybackMonth: firstOperating >= 0 && paybackIndex > 0 ? (months[paybackIndex]?.month ?? null) : null,
    breakEvenMonth: breakEven?.month ?? null,
    npv: round2(npv(flows, resolved.drivers.discountRate)),
    irr: irr(flows),
    stabilisedEbitda: round2(stabilisedYear.reduce((sum, m) => sum + m.ebitda, 0)),
    stabilisedRevenue: round2(stabilisedYear.reduce((sum, m) => sum + m.revenue, 0)),
  }
}

export function yearly(rows: readonly MonthRow[]): YearRow[] {
  const byYear = new Map<number, YearRow>()
  for (const r of rows) {
    const year = Number(r.month.slice(0, 4))
    const prev = byYear.get(year) ?? { year, capex: 0, revenue: 0, opex: 0, ebitda: 0, depreciation: 0, tax: 0, netIncome: 0, freeCash: 0 }
    byYear.set(year, {
      year,
      capex: prev.capex + r.capex,
      revenue: prev.revenue + r.revenue,
      opex: prev.opex + r.opex,
      ebitda: prev.ebitda + r.ebitda,
      depreciation: prev.depreciation + r.depreciation,
      tax: prev.tax + r.tax,
      netIncome: prev.netIncome + r.netIncome,
      freeCash: prev.freeCash + r.freeCash,
    })
  }
  return [...byYear.values()].toSorted((a, b) => a.year - b.year)
}
